void can_lut_reset (void)
{
  UInt16 index   = 0 ;

  CAN_SFF_SA     = 0 ;
  CAN_SFF_GRP_SA = 0 ;

  CAN_EFF_SA     = 0 ;
  CAN_EFF_GRP_SA = 0 ;

  CAN_EOT        = 0 ;

  can_lut_counters.std     = 0 ;
  can_lut_counters.std_grp = 0 ;
  can_lut_counters.ext     = 0 ;
  can_lut_counters.ext_grp = 0 ;

  do
    {
      CAN_AFRAM [index] = 0 ;
    }
  while (++index < 512) ;
}

